void testDoubleVisibleSignatureOnEncryptedFile(boolean externallySign) throws IOException, CMSException, OperatorCreationException, GeneralSecurityException, TSPException, CertificateVerificationException {
    // sign PDF
    String inPath = "target/pdfs/PDFBOX-2469-1-AcroForm-AES128.pdf";
    CreateVisibleSignature signing;
