    if (!TestPDFToImage.doTestFile(new File(testDirIn, filename), testDirIn.getAbsolutePath(), testDirOut.getAbsolutePath())) {
        fail("Rendering failed or is not identical, see in " + testDirOut);
    }
}

/**
 * Compress a document, that contains acroform fields and touch the expected fields.
 *
 * @throws Exception Shall be thrown, when compressing the document failed.
 */
@Test
void testCompressAcroformDoc() throws Exception {
    File source = new File(inDir, "acroform.pdf");
    File target = new File(outDir, "acroform.pdf");
    PDDocument document = Loader.loadPDF(source);
    try {
        document.save(target);
    } finally {
        document.close();
    }
    document = Loader.loadPDF(target);
    try {
        assertEquals(1, document.getNumberOfPages(), "The number of pages should not have changed, during compression.");
        PDPage page = document.getPage(0);
        List<PDAnnotation> annotations = page.getAnnotations();
        assertEquals(13, annotations.size(), "The number of annotations should not have changed");
        assertEquals("TextField", annotations.get(0).getCOSObject().getNameAsString(COSName.T), "The 1. annotation should have been a text field.");
        assertEquals("Button", annotations.get(1).getCOSObject().getNameAsString(COSName.T), "The 2. annotation should have been a button.");
        assertEquals("CheckBox1", annotations.get(2).getCOSObject().getNameAsString(COSName.T), "The 3. annotation should have been a checkbox.");
        assertEquals("CheckBox2", annotations.get(3).getCOSObject().getNameAsString(COSName.T), "The 4. annotation should have been a checkbox.");
        assertEquals("TextFieldMultiLine", annotations.get(4).getCOSObject().getNameAsString(COSName.T), "The 5. annotation should have been a multiline textfield.");
        assertEquals("TextFieldMultiLineRT", annotations.get(5).getCOSObject().getNameAsString(COSName.T), "The 6. annotation should have been a multiline textfield.");
        assertNotNull(annotations.get(6).getCOSObject().getItem(COSName.PARENT), "The 7. annotation should have had a parent entry.");
        assertEquals("GroupOption", annotations.get(6).getCOSObject().getCOSDictionary(COSName.PARENT).getNameAsString(COSName.T), "The 7. annotation's parent should have been a GroupOption.");
        assertNotNull(annotations.get(7).getCOSObject().getItem(COSName.PARENT), "The 8. annotation should have had a parent entry.");
        assertEquals("GroupOption", annotations.get(7).getCOSObject().getCOSDictionary(COSName.PARENT).getNameAsString(COSName.T), "The 8. annotation's parent should have been a GroupOption.");
        assertEquals("ListBox", annotations.get(8).getCOSObject().getNameAsString(COSName.T), "The 9. annotation should have been a ListBox.");
        assertEquals("ListBoxMultiSelect", annotations.get(9).getCOSObject().getNameAsString(COSName.T), "The 10. annotation should have been a ListBox Multiselect.");
        assertEquals("ComboBox", annotations.get(10).getCOSObject().getNameAsString(COSName.T), "The 11. annotation should have been a ComboBox.");
