 * PDFBOX-5115: U+00AD (soft hyphen) should work with WinAnsiEncoding.
 */
@Test
void testSoftHyphen() throws IOException {
    String text = "- \u00AD";
    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    try (PDDocument doc = new PDDocument()) {
        PDPage page = new PDPage();
        doc.addPage(page);
        PDFont font1 = PDType1Font.HELVETICA;
        PDFont font2 = PDType0Font.load(doc, PDFontTest.class.getResourceAsStream("/org/apache/pdfbox/resources/ttf/LiberationSans-Regular.ttf"));
